    sfu_basketball_03_34/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_34/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_34/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_34/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_34/trajectory/gopro_calibs.csv \
    sfu_basketball_03_36/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_36/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_36/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_36/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_36/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_36/trajectory/gopro_calibs.csv \
    sfu_basketball_03_56/frame_aligned_videos/cam01.mp4 \
